CREATE OR REPLACE FUNCTION public.hall_inquiry_record_reply(p_dispatch_id uuid, p_operator_user_id uuid, p_raw_text text, p_outcome text, p_event_at timestamp with time zone, p_place_note text, p_price_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
